// virtual image plane group
const virtGroup = new THREE.Group(); scene.add(virtGroup);
const virtPlane = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 2.4),
  new THREE.MeshBasicMaterial({ color: 0xc8d0d0, transparent: true, opacity: 0.25, side: THREE.DoubleSide, depthWrite: false }));
virtGroup.add(virtPlane);
{
  const eg = new THREE.EdgesGeometry(virtPlane.geometry);
  virtGroup.add(new THREE.LineSegments(eg, new THREE.LineBasicMaterial({ color: 0x8a9494 })));
}
// green local axes + right-angle marker
function greenArrow(dir) {
  const a = new THREE.ArrowHelper(dir, new THREE.Vector3(), 1.0, 0x22cc22, 0.12, 0.07);
  virtGroup.add(a);
}
greenArrow(new THREE.Vector3(1, 0, 0));
greenArrow(new THREE.Vector3(0, 1, 0));
{
  const g = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0.18, 0, 0.001), new THREE.Vector3(0.18, 0.18, 0.001), new THREE.Vector3(0, 0.18, 0.001)]);
  virtGroup.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0x22cc22 })));
}
registerInteractive(virtPlane, { title: 'Virtual image plane', body: 'An imaginary plane at z = +f in front of the pinhole. The continuous projection lands at (x, y) = (f·X/Z, f·Y/Z) — same orientation as the scene, no flip.' });

// continuous projection dot
const projDot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 14, 14), matBlue);
scene.add(projDot);

// sensor group (rebuilt on param change)
let sensorGroup = null;
let snappedQuad = null, neighborQuads = [];
let principalDot = null;

function buildSensor() {
  if (sensorGroup) { scene.remove(sensorGroup); _disposeObject(sensorGroup); }
  sensorGroup = new THREE.Group();
  const { w, N } = state;
  const M = Math.round(N * 0.75);
  const h = w * 0.75;
  const pts = [];
  for (let i = 0; i <= N; i++) { const x = -w / 2 + i * w / N; pts.push(x, -h / 2, 0, x, h / 2, 0); }
  for (let j = 0; j <= M; j++) { const y = -h / 2 + j * h / M; pts.push(-w / 2, y, 0, w / 2, y, 0); }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
  sensorGroup.add(new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color: 0x9aa4a4 })));
  // backing
  const back = new THREE.Mesh(new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ color: 0xeef2f2, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false }));
  back.position.z = -0.005; sensorGroup.add(back);
  // snapped cell + neighbor tints
  snappedQuad = new THREE.Mesh(new THREE.PlaneGeometry(1, 1),
    new THREE.MeshBasicMaterial({ color: 0xe03030, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false }));
  snappedQuad.position.z = -0.002; sensorGroup.add(snappedQuad);
  neighborQuads = [];
  const ncol = [0xf0d020, 0xa0e050, 0xf0d020, 0xa0e050, 0xf0d020, 0xa0e050, 0xf0d020, 0xa0e050];
  for (let k = 0; k < 8; k++) {
    const q = new THREE.Mesh(new THREE.PlaneGeometry(1, 1),
      new THREE.MeshBasicMaterial({ color: ncol[k], transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false }));
    q.position.z = -0.003; sensorGroup.add(q); neighborQuads.push(q);
  }
  // principal point dot
  principalDot = new THREE.Mesh(new THREE.SphereGeometry(0.05, 12, 12), matBlack);
  sensorGroup.add(principalDot);
  sensorGroup.position.z = -state.f;
  scene.add(sensorGroup);
  registerInteractive(back, { title: 'Image plane / sensor', body: 'The physical M×N pixel grid at z = −f behind the pinhole. The image here is flipped relative to the scene, and continuous coordinates are snapped (quantized) to integer pixel indices.' });
}

// f dimension arrow (double-headed)
const fArrowGroup = new THREE.Group(); scene.add(fArrowGroup);
function buildFArrow() {
  while (fArrowGroup.children.length) { const c = fArrowGroup.children.pop(); _disposeObject(c); }
  const y = -1.7;
  const g = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, y, 0), new THREE.Vector3(0, y, -state.f)]);
  fArrowGroup.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0x111111 })));
  const c1 = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 10), matBlack);
  c1.position.set(0, y, -0.08); c1.rotation.x = -Math.PI / 2; fArrowGroup.add(c1);
  const c2 = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 10), matBlack);
  c2.position.set(0, y, -state.f + 0.08); c2.rotation.x = Math.PI / 2; fArrowGroup.add(c2);
}

// object panel at z=6
{
  const panel = new THREE.Group();
  const sq = (s, c, x, y, z) => {
