    m.position.set(x, y, z); panel.add(m); return m;
  };
  sq(2.5, 0xa0e050, 0, 0, 0);
  sq(0.9, 0xf0d020, -0.55, -0.55, 0.01);
  sq(0.9, 0xf0d020, 0.55, 0.55, 0.01);
  sq(0.9, 0xf0d020, 0.55, -0.55, 0.01);
  // red diagonal band
  const band = new THREE.Mesh(new THREE.PlaneGeometry(3.0, 0.55), new THREE.MeshBasicMaterial({ color: 0xe03030, side: THREE.DoubleSide }));
  band.rotation.z = Math.PI / 4; band.position.set(0, 0.72, 0.02); panel.add(band);
  panel.position.set(1.2, 0.9, 6);
  scene.add(panel);
  registerInteractive(sq(0.01, 0xffffff, 0, 0, -0.01), { title: '3D object', body: 'The object in the world containing point P. Light from P travels along the dashed ray through the pinhole onto the sensor.' });
}

// ── labels ──
const lbl = {
  sensor: addLabel('Image plane / sensor', new THREE.Vector3(), { fontSize: '15px' }),
  npix: addLabel('N pixels', new THREE.Vector3(), { fontSize: '12px' }),
  mpix: addLabel('M pixels', new THREE.Vector3(), { fontSize: '12px' }),
  w: addLabel('<i>w</i>', new THREE.Vector3(), { fontSize: '14px' }),
  cc: addLabel('Camera center', new THREE.Vector3(0.1, -0.55, 0.15), { fontSize: '14px' }),
  vip: addLabel('Virtual image plane', new THREE.Vector3(), { fontSize: '13px' }),
  opt: addLabel('Optical / principal axis', new THREE.Vector3(0, 0.35, 3.4), { fontSize: '14px' }),
  P: addLabel('<b>P</b>', new THREE.Vector3(), { fontSize: '17px' }),
  x: addLabel('<i>x</i>', new THREE.Vector3(), { color: '#16a016', fontSize: '15px' }),
  y: addLabel('<i>y</i>', new THREE.Vector3(), { color: '#16a016', fontSize: '15px' }),
  f: addLabel('<i>f</i>', new THREE.Vector3(), { fontSize: '16px' }),
  Xc: addLabel('X<sub>c</sub>', new THREE.Vector3(1.75, 0.12, 0), { fontSize: '15px' }),
  Yc: addLabel('Y<sub>c</sub>', new THREE.Vector3(0.15, 2.35, 0), { fontSize: '15px' }),
  Zc: addLabel('Z<sub>c</sub>', new THREE.Vector3(0.15, -0.25, 5.4), { fontSize: '15px' }),
};

// ── readout ──
const readoutEl = document.getElementById('readout');

function update() {
  const { f, w, N } = state;
  const M = Math.round(N * 0.75);
  const h = w * 0.75;
  const px = w / N, py = h / M;
  // positions
  pMesh.position.copy(P);
  lbl.P.pos.copy(P).add(new THREE.Vector3(0.18, 0.22, 0));
  // continuous projection on virtual plane
  const cx = f * P.x / P.z, cy = f * P.y / P.z;
  projDot.position.set(cx, cy, f);
  virtGroup.position.z = f;
  lbl.vip.pos.set(0, -1.45, f);
  lbl.x.pos.set(1.1, 0.08, f);
  lbl.y.pos.set(0.12, 1.1, f);
  // sensor intersection (mirrored through pinhole)
  const sx = -f * P.x / P.z, sy = -f * P.y / P.z;
  // rays
  ray1.geometry.dispose();
  ray1.geometry = new THREE.BufferGeometry().setFromPoints([P.clone(), new THREE.Vector3(0, 0, 0)]);
  ray1.computeLineDistances();
  ray2.geometry.dispose();
  ray2.geometry = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), new THREE.Vector3(sx, sy, -f)]);
  ray2.computeLineDistances();
