const state = { f: 2, w: 2.4, N: 12, mode: 'xy' };
const P = new THREE.Vector3(1.2, 0.9, 4.5);
const OBJ_Z = 6;                 // object panel depth
const VIRT_SIZE = 3.2;           // virtual plane size (larger than sensor, per source)

const matBlack = new THREE.MeshBasicMaterial({ color: 0x111111 });
const matBlue = new THREE.MeshBasicMaterial({ color: 0x33aaff });

// pinhole
const pinhole = new THREE.Mesh(new THREE.SphereGeometry(0.07, 16, 16), matBlack);
scene.add(pinhole);
registerInteractive(pinhole, { title: 'Camera center (pinhole)', body: 'All rays from scene points pass through this single point — the origin of the camera frame (Xc, Yc, Zc).' });

// camera axes
function axis(dir, len) {
  const a = new THREE.ArrowHelper(dir.clone().normalize(), new THREE.Vector3(), len, 0x111111, 0.16, 0.09);
  scene.add(a); return a;
}
axis(new THREE.Vector3(1, 0, 0), 1.6);
axis(new THREE.Vector3(0, 1, 0), 2.2);
axis(new THREE.Vector3(0, 0, 1), 5.6);

// P sphere
const pMesh = new THREE.Mesh(new THREE.SphereGeometry(0.09, 20, 20), matBlue);
pMesh.position.copy(P);
scene.add(pMesh);
registerInteractive(pMesh, { title: 'Scene point P', body: 'A 3D point in camera coordinates P = (X, Y, Z). Drag it: its continuous projection and its snapped sensor pixel move together.' });

// rays
const ray1 = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineDashedMaterial({ color: 0x888888, dashSize: 0.12, gapSize: 0.08 }));
const ray2 = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineDashedMaterial({ color: 0x222222, dashSize: 0.12, gapSize: 0.08 }));
scene.add(ray1, ray2);

// ── virtual image plane group ──
const virtGroup = new THREE.Group(); scene.add(virtGroup);
const virtPlane = new THREE.Mesh(new THREE.PlaneGeometry(VIRT_SIZE, VIRT_SIZE),
