    new THREE.Vector3(0.16, 0, 0.001), new THREE.Vector3(0.16, 0.16, 0.001), new THREE.Vector3(0, 0.16, 0.001)]);
  greenGroup.add(new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0x22cc22 })));
}

// continuous projection dot
const projDot = new THREE.Mesh(new THREE.SphereGeometry(0.055, 14, 14), matBlue);
