// ── sensor group (rebuilt on param change) ──
let sensorGroup = null;
let snappedQuad = null, neighborQuads = [];
let principalDot = null;
let imgPatch = null;   // inverted projected object image on the sensor

function buildSensor() {
  if (sensorGroup) { scene.remove(sensorGroup); _disposeObject(sensorGroup); }
  sensorGroup = new THREE.Group();
  const { w, N, f } = state;
  const M = Math.round(N * 0.75);
  const h = w * 0.75;
  const pts = [];
  for (let i = 0; i <= N; i++) { const x = -w / 2 + i * w / N; pts.push(x, -h / 2, 0, x, h / 2, 0); }
  for (let j = 0; j <= M; j++) { const y = -h / 2 + j * h / M; pts.push(-w / 2, y, 0, w / 2, y, 0); }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
  sensorGroup.add(new THREE.LineSegments(g, new THREE.LineBasicMaterial({ color: 0x9aa4a4 })));
  // backing
  const back = new THREE.Mesh(new THREE.PlaneGeometry(w, h),
    new THREE.MeshBasicMaterial({ color: 0xeef2f2, transparent: true, opacity: 0.35, side: THREE.DoubleSide, depthWrite: false }));
  back.position.z = -0.006; sensorGroup.add(back);

  // ── inverted projected image of the object panel on the sensor ──
  // panel spans [-1.25,1.25]² at z=OBJ_Z (local, panel at (1.2,0.9)); its pinhole
  // projection lands at scale s = f/OBJ_Z, flipped in both axes.
  imgPatch = new THREE.Group();
  const s = f / OBJ_Z;
  const pcx = 1.2, pcy = 0.9;   // panel center (world xy)
  const flat = (wd, ht, c, lx, ly, op, rot) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(wd, ht),
      new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: op, side: THREE.DoubleSide, depthWrite: false }));
    // flip through pinhole: sensor xy = -(world xy)*s  (panel-local offset about panel center)
    m.position.set(-(pcx + lx) * s, -(pcy + ly) * s, -0.001);
    if (rot) m.rotation.z = rot;
    imgPatch.add(m); return m;
  };
  flat(2.5 * s, 2.5 * s, 0xa0e050, 0, 0, 0.55);                                  // green square
  flat(0.9 * s, 0.9 * s, 0xf0d020, -0.55, -0.55, 0.65);                          // yellow subs
  flat(0.9 * s, 0.9 * s, 0xf0d020, 0.55, 0.55, 0.65);
  flat(0.9 * s, 0.9 * s, 0xf0d020, 0.55, -0.55, 0.65);
  flat(3.0 * s, 0.55 * s, 0xe03030, 0, 0.72, 0.6, Math.PI / 4);                  // red diagonal band
  sensorGroup.add(imgPatch);

  // snapped cell + neighbor tints
  snappedQuad = new THREE.Mesh(new THREE.PlaneGeometry(1, 1),
    new THREE.MeshBasicMaterial({ color: 0xe03030, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false }));
  snappedQuad.position.z = -0.004; sensorGroup.add(snappedQuad);
  neighborQuads = [];
  const ncol = [0xf0d020, 0xa0e050, 0xf0d020, 0xa0e050, 0xf0d020, 0xa0e050, 0xf0d020, 0xa0e050];
  for (let k = 0; k < 8; k++) {
    const q = new THREE.Mesh(new THREE.PlaneGeometry(1, 1),
      new THREE.MeshBasicMaterial({ color: ncol[k], transparent: true, opacity: 0.55, side: THREE.DoubleSide, depthWrite: false }));
    q.position.z = -0.005; sensorGroup.add(q); neighborQuads.push(q);
  }
  // principal point dot
  principalDot = new THREE.Mesh(new THREE.SphereGeometry(0.05, 12, 12), matBlack);
  sensorGroup.add(principalDot);
  sensorGroup.position.z = -state.f;
  scene.add(sensorGroup);
  registerInteractive(back, { title: 'Image plane / sensor', body: 'The physical M×N pixel grid at z = −f behind the pinhole. The faint colored patch is the inverted image of the object; the red cell is the snapped pixel containing P\'s ray.' });
}

// ── f dimension: bracket with end ticks + double-headed arrow ──
const fArrowGroup = new THREE.Group(); scene.add(fArrowGroup);
function buildFArrow() {
  while (fArrowGroup.children.length) { const c = fArrowGroup.children.pop(); _disposeObject(c); }
  const y = -1.85;
  const mat = new THREE.LineBasicMaterial({ color: 0x111111 });
  // main shaft with arrowheads both ends
  const g = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, y, 0), new THREE.Vector3(0, y, -state.f)]);
  fArrowGroup.add(new THREE.Line(g, mat));
  const c1 = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 10), matBlack);
  c1.position.set(0, y, -0.08); c1.rotation.x = -Math.PI / 2; fArrowGroup.add(c1);
  const c2 = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.16, 10), matBlack);
  c2.position.set(0, y, -state.f + 0.08); c2.rotation.x = Math.PI / 2; fArrowGroup.add(c2);
  // end ticks (vertical witness lines)
  const tick = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, y + 0.18, 0), new THREE.Vector3(0, y - 0.12, 0),
    new THREE.Vector3(0, y + 0.18, -state.f), new THREE.Vector3(0, y - 0.12, -state.f)]);
  fArrowGroup.add(new THREE.LineSegments(tick, mat));
}

// ── object panel at z=6 (far right) ──
{
  const panel = new THREE.Group();
  const sq = (s, c, x, y, z) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(s, s), new THREE.MeshBasicMaterial({ color: c, side: THREE.DoubleSide }));
    m.position.set(x, y, z); panel.add(m); return m;
  };
  sq(2.5, 0xa0e050, 0, 0, 0);
  sq(0.9, 0xf0d020, -0.55, -0.55, 0.01);
  sq(0.9, 0xf0d020, 0.55, 0.55, 0.01);
  sq(0.9, 0xf0d020, 0.55, -0.55, 0.01);
  const band = new THREE.Mesh(new THREE.PlaneGeometry(3.0, 0.55), new THREE.MeshBasicMaterial({ color: 0xe03030, side: THREE.DoubleSide }));
  band.rotation.z = Math.PI / 4; band.position.set(0, 0.72, 0.02); panel.add(band);
