{
  const ray = new THREE.Raycaster();
  const ptr = new THREE.Vector2();
  const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), -P.z);
  let dragging = false;
  canvas.addEventListener('pointerdown', (e) => {
    const r = canvas.getBoundingClientRect();
    ptr.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
    ray.setFromCamera(ptr, camera);
    if (ray.intersectObject(pMesh).length) {
      dragging = true; controls.enabled = false;
      dragPlane.constant = -P.z;
    }
  });
  window.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const r = canvas.getBoundingClientRect();
    ptr.set(((e.clientX - r.left) / r.width) * 2 - 1, -((e.clientY - r.top) / r.height) * 2 + 1);
    ray.setFromCamera(ptr, camera);
    const hit = new THREE.Vector3();
    if (ray.ray.intersectPlane(dragPlane, hit)) {
      P.x = Math.max(-2, Math.min(2.5, hit.x));
      P.y = Math.max(-1.5, Math.min(2, hit.y));
      update();
    }
  });
  window.addEventListener('pointerup', () => { dragging = false; controls.enabled = true; });
}

