let tween = null;
function goToStep(i) {
  const s = steps[i];
  const targets = {};
  if (s.state.focalLength != null) targets.f = s.state.focalLength;
  if (s.state.sensorWidth != null) targets.w = s.state.sensorWidth;
  if (s.state.resolution != null) targets.N = s.state.resolution;
  if (s.state.mode) {
    state.mode = s.state.mode;
    document.querySelectorAll('.coordBtn').forEach(x => x.classList.toggle('active', x.dataset.mode === state.mode));
  }
  const start = { f: state.f, w: state.w, N: state.N };
  const t0 = performance.now();
  tween = () => {
    const k = Math.min(1, (performance.now() - t0) / 700);
    const e = k * (2 - k);
    for (const key of Object.keys(targets)) state[key] = start[key] + (targets[key] - start[key]) * e;
    document.getElementById('focalLength').value = state.f;
    document.getElementById('sensorWidth').value = state.w;
    document.getElementById('resolution').value = state.N;
    rebuild();
    if (k < 1) requestAnimationFrame(tween); else tween = null;
  };
  if (!tween) requestAnimationFrame(tween);
  const sn = document.getElementById('stepNarration');
  sn.style.display = '';
  sn.innerHTML = `<b>${s.title}.</b> ${s.narration}`;
}
